SELECT
  min(latitude) AS min_latitude,
  min(longitude) AS min_longitude,
  max(latitude) AS max_latitude,
  max(longitude) AS max_longitude,
  cast(sum(population) as integer) AS population
FROM yemen_2020
WHERE
  type = 'total_population'
  AND ST_Within(
    ST_Point(longitude, latitude),
    ST_Polygon('POLYGON ((44.988166 12.994768,45.2520411 13.7935293,45.9334476 14.0589982,46.0223137 14.2184115,45.5457299 14.7112863,45.5152383 15.1120327,46.3533359 15.6890439,47.0144206 16.4492282,46.9608489 16.9714215,47.4711956 17.2046713,48.1250127 18.1726908,49.2000742 18.670387,52.0764496 19.0447174,53.06207 16.7936003,53.1689021 16.637423,52.4292599 16.4151799,52.1948994 16.1566674,52.1935306 15.6221585,50.7652933 15.0693579,50.1769706 14.893863,49.0889221 14.4868465,48.8426331 14.0516882,48.3582336 13.992257,47.9795086 14.002853,47.3876476 13.6263205,46.6076776 13.4153135,45.7263471 13.3189789,45.3425624 12.9903385,44.988166 12.994768))')
  );
